/**
 * _test_tab_report_fallback.ts — RF-1「tab 回合结束但没调 tab-finish ⇒ 自动落 unconfirmed 结果」验收
 *
 * 任务书：`plans/20261018_tab_report_fallback_task_brief.md`
 * 实现报告：`plans/20261018_tab_report_fallback_impl.md`
 *
 * 覆盖七条（编号与任务书一致）：
 *   1. 回合结束 + 无 result.json ⇒ 自动写入 status="unconfirmed" + autoGenerated=true
 *   2. 已有 result.json（正常 tab-finish）⇒ **不覆盖**，内容逐字节不变
 *   3. status 永不为 "completed"（断言）
 *   4. 幂等：同一 runId 连续两次 agent_settled ⇒ 只写一次（finishedAt 不变）
 *   5. 写失败（注入会抛的写函数）⇒ **不抛到调用方**
 *   6. 无 dispatch 记录的 runId ⇒ **不生成**
 *   7. deriveTabSupervisionState：terminal + resultMissing ⇒ BLOCKED_USER（非 DONE）；
 *      且 phase==="unconfirmed" + active ⇒ BLOCKED_USER
 *
 * 接线纪律（AGENTS R-4 事故教训：「测试直调函数 ≠ 真接线」）：
 *   第 1/2/3/4/6 条**全部经真实入口** `registerTabTelemetry(pi)` + `pi.emit("agent_settled")`
 *   （fake pi 收集 handler，同 `_test_tab_runs_runtime.ts::makeFakePi`），**不直调** writeSettlementFallback。
 *   第 5 条是**边界/注入点**测试，直调 writeSettlementFallback（注入点是函数参数，事件体无法注入抛错写）。
 *   两条都要：经入口证行为，直调证 never-throw 边界。
 *
 * 运行：npx tsx extensions/_test_tab_report_fallback.ts
 */
import assert from "node:assert/strict";
import { existsSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

// 身份隔离：任何运行器（含子 agent）里行为一致
delete process.env.PI_SUBAGENT;
delete process.env.PI_TAB_RUN_ID;
delete process.env.PI_TAB_RUNS_DIR;

// 隔离 runtime 状态（receipts / journal / claims / suppressions / mailbox / registry）——
// 同 _test_event_bus.ts 的 PI_RUNTIME_DIR 隔离模式。兑底结果的唤醒链走 injection-gate 收据
// `run-<runId>-<status>`；固定 runId 若落进真实 ~/.pi/agent/runtime/ 会跨 run 残留
// "injected-already" ⇒ 本测试第二次起必红（2026-10-18 实测：8(b) gate reject already-injected），
// 且测试会污染真实 runtime（journal 假事件/收据）。runtime dir 在调用时惰性读取，
// 在此（导入后、任何 runtime 调用前）设置即可全量隔离。
process.env.PI_RUNTIME_DIR = mkdtempSync(join(tmpdir(), "tab-rf1-runtime-"));

import {
	archiveStaleTabRuns,
	tabResultPath,
	validateTabResult,
	writeJsonAtomic,
	writeTabDispatch,
	type TabDispatchRecord,
} from "./tab-runs.ts";
import { registerTabTelemetry, writeSettlementFallback } from "./tab-runs-runtime.ts";
import { deriveTabSupervisionState, type FrontierSourceTab, type FrontierSupervision } from "./runtime/autonomy/frontier.ts";
import { classifyDispatch } from "./runtime/frontier-carriers.ts";
import { onTabResultFile } from "./event-bus.ts";
import { setCurrentSessionId } from "./identity.ts";

// ── 计数与隔离工具 ────────────────────────────────────────────────
let passed = 0;
let failed = 0;
function check(name: string, fn: () => void): void {
	try {
		fn();
		passed++;
		console.log(`  ✓ ${name}`);
	} catch (e) {
		failed++;
		console.error(`  ✗ ${name}`);
		console.error(`    ${String((e as Error)?.message ?? e)}`);
	}
}

/** 真实运行时形状的 dispatch 账本（字段与 launch-tabs 写入的一致）。 */
function mkDispatch(id: string, taskId = "RF-1"): TabDispatchRecord {
	return {
		id,
		version: 1,
		taskId,
		mode: "workflow",
		cwd: "G:\\code\\worktrees\\GreenCAD-219",
		dispatchedAt: new Date().toISOString(),
		dispatchStatus: "dispatched",
	};
}

/** fake pi：捕获 pi.on 的 handler（同 `_test_tab_runs_runtime.ts::makeFakePi` 的最小集）。 */
function makeFakePi() {
	const handlers: Record<string, Array<(event: unknown, ctx: unknown) => unknown>> = {};
	const tools: Array<{ name: string }> = [];
	return {
		handlers,
		tools,
		registerTool(tool: { name: string }) {
			tools.push(tool);
		},
		registerCommand() {},
		on(event: string, handler: (event: unknown, ctx: unknown) => unknown) {
			handlers[event] = handlers[event] ?? [];
			handlers[event].push(handler);
		},
		async emit(event: string, ev: unknown, ctx: unknown = {}) {
			for (const h of handlers[event] ?? []) await h(ev, ctx);
		},
		findTool(name: string) {
			return tools.find((t) => t.name === name);
		},
	};
}

/** 模拟一整个 tab 回合：assistant 消息落地 → agent_settled。 */
async function runOneTurn(pi: ReturnType<typeof makeFakePi>, text: string, stopReason = "stop"): Promise<void> {
	await pi.emit("message_end", {
		message: {
			id: `m_${Math.random().toString(36).slice(2, 8)}`,
			role: "assistant",
			stopReason,
			timestamp: new Date().toISOString(),
			content: [{ type: "text", text }],
		},
	}, {});
	await pi.emit("agent_settled", {}, { isIdle: () => true });
}

function isoAgo(ms: number): string {
	return new Date(Date.now() - ms).toISOString();
}

function mkTab(over: Partial<FrontierSourceTab> = {}): FrontierSourceTab {
	return {
		runId: "tab_rf1",
		repoPath: "g:/code/x",
		phase: "waiting",
		stop: "stop",
		idleMs: 60_000,
		needsHuman: false,
		gate: "ok",
		staleOver: false,
		overdue: 0,
		resultMissing: true,
		pidAlive: true,
		...over,
	};
}

// ════════════ 1. 回合结束 + 无 result.json ⇒ 自动写 unconfirmed ════════════
console.log('1. 回合结束 + 无 result.json ⇒ 自动写入 status="unconfirmed" + autoGenerated=true（经 agent_settled 真实派发）');
{
	const runsDir = mkdtempSync(join(tmpdir(), "tab-rf1-"));
	const runId = "tab_rf1_a";
	try {
		writeTabDispatch(runsDir, mkDispatch(runId, "TASK-RF1-A"));
		const pi = makeFakePi();
		registerTabTelemetry(pi, { tabRunId: runId, runsDir });

		let outcome = "";
		void outcome;
		// 真实入口：先落一条 assistant 文本 + 回合结束
		await runOneTurn(pi, "我把实现写完了但忘了回报", "stop");

		// 1(e) 的夹具准备（超长 finalText）：同样经真实入口
		const runId2 = "tab_rf1_long";
		writeTabDispatch(runsDir, mkDispatch(runId2));
		const pi2 = makeFakePi();
		registerTabTelemetry(pi2, { tabRunId: runId2, runsDir });
		await runOneTurn(pi2, "B".repeat(5000));

		check("1(a) 文件真的存在（不是内存假象）", () => {
			assert.ok(readFileSync(tabResultPath(runsDir, runId), "utf8").length > 0, "tab-runs/<runId>.result.json 必须落盘");
		});
		check('1(b) status === "unconfirmed" 且 autoGenerated === true', () => {
			const raw = JSON.parse(readFileSync(tabResultPath(runsDir, runId), "utf8")) as Record<string, unknown>;
			assert.equal(raw.status, "unconfirmed");
			assert.equal(raw.autoGenerated, true);
			assert.equal(raw.id, runId);
			assert.equal(raw.taskId, "TASK-RF1-A", "taskId 取 dispatch.taskId");
			assert.ok(typeof raw.finishedAt === "string" && Number.isFinite(Date.parse(raw.finishedAt)), "finishedAt 必须是可解析 ISO");
			assert.ok(Array.isArray(raw.artifacts) && raw.artifacts.length === 0, "artifacts 缺省 []（兜底无交付物声明）");
			assert.ok(Array.isArray(raw.openIssues) && raw.openIssues.length >= 1, "openIssues 必须显式写「未调用 tab-finish」");
			assert.match(String(raw.summary), /未调用 tab-finish/, "summary 必须自证「未回报」");
		});
		check("1(c) 兜底结果能通过读侧校验（否则对全系统不可见 = dead code）", () => {
			const raw = JSON.parse(readFileSync(tabResultPath(runsDir, runId), "utf8"));
			const v = validateTabResult(raw);
			assert.equal(v.ok, true, `读侧校验必须通过：${v.errors.join("; ")}`);
			assert.equal(v.value!.status, "unconfirmed");
		});
		check("1(d) finalText 携带本回合最后一条 assistant 文本（截断 ≤2000）", () => {
			const raw = JSON.parse(readFileSync(tabResultPath(runsDir, runId), "utf8")) as { finalText?: string };
			assert.equal(raw.finalText, "我把实现写完了但忘了回报");
		});
		check("1(e) finalText 截断上限 2000（超长文本不得整段落盘）", () => {
			const raw = JSON.parse(readFileSync(tabResultPath(runsDir, "tab_rf1_long"), "utf8")) as { finalText?: string };
			assert.equal(raw.finalText?.length, 2000, "必须恰好截断到 2000");
		});
	} finally {
		rmSync(runsDir, { recursive: true, force: true });
	}
}

// ════════════ 2. 已有 result.json ⇒ 不覆盖（逐字节不变）════════════════
console.log("2. 已有 result.json（正常 tab-finish）⇒ 不覆盖，内容逐字节不变（经 agent_settled 真实派发）");
{
	const runsDir = mkdtempSync(join(tmpdir(), "tab-rf1-b-"));
	const runId = "tab_rf1_b";
	try {
		writeTabDispatch(runsDir, mkDispatch(runId));
		// 手工落一份「真 tab-finish」结果（结构与 validateTabResult 接受的三态一致）
		const real = {
			id: runId,
			taskId: "TASK-RF1-B",
			status: "completed",
			finishedAt: isoAgo(1000),
			summary: "真 tab-finish 报告",
			finalText: "done",
			artifacts: ["plans/x.md"],
		};
		writeJsonAtomic(tabResultPath(runsDir, runId), real);
		const before = readFileSync(tabResultPath(runsDir, runId), "utf8");

		const pi = makeFakePi();
		registerTabTelemetry(pi, { tabRunId: runId, runsDir });
		await runOneTurn(pi, "回合结束（不应触发兜底）");

		check("2(a) 文件内容逐字节不变", () => {
			const after = readFileSync(tabResultPath(runsDir, runId), "utf8");
			assert.equal(after, before, "真 tab-finish 结果不得被兜底覆盖/重写");
		});
		check("2(b) 语义仍是 completed（未被改写成 unconfirmed）", () => {
			const raw = JSON.parse(readFileSync(tabResultPath(runsDir, runId), "utf8")) as Record<string, unknown>;
			assert.equal(raw.status, "completed");
			assert.equal(raw.autoGenerated, undefined, "真结果不得被加上 autoGenerated 标记");
		});
	} finally {
		rmSync(runsDir, { recursive: true, force: true });
	}
}

// ════════════ 3. status 永不为 completed ════════════════════════════════
console.log('3. status 永不为 "completed"（多轮 + 多形状 + 直接构造面均为 unconfirmed）');
{
	const runsDir = mkdtempSync(join(tmpdir(), "tab-rf1-c-"));
	try {
		// 夹具（全部经真实入口 agent_settled 派发）
		const runIdC1 = "tab_rf1_c1";
		writeTabDispatch(runsDir, mkDispatch(runIdC1));
		const piC1 = makeFakePi();
		registerTabTelemetry(piC1, { tabRunId: runIdC1, runsDir });
		await runOneTurn(piC1, "第一轮");
		check("3(a) 多轮 settle 的兜底 result 仍不是 completed", () => {
			const raw = JSON.parse(readFileSync(tabResultPath(runsDir, "tab_rf1_c1"), "utf8")) as Record<string, unknown>;
			assert.notEqual(raw.status, "completed");
			assert.equal(raw.status, "unconfirmed");
		});
		check("3(b) 无 dispatch.taskId 时 taskId 回退 \"unknown\"（仍不得变 completed）", () => {
			// dispatch 记录 taskId 为空串（launch 失败/直开历史形状）—— 这种账本读侧自身校验不过，
			// 所以直接透传 dispatch 形状，隔离验证「taskId 回退」而不是「账本校验」。
			const runId = "tab_rf1_c2";
			const out = writeSettlementFallback({
				runsDir, runId, lastAssistantText: "x",
				dispatch: { ...mkDispatch(runId), taskId: "" },
			});
			assert.equal(out, "written");			const raw = JSON.parse(readFileSync(tabResultPath(runsDir, runId), "utf8")) as Record<string, unknown>;
			assert.equal(raw.taskId, "unknown", "空 taskId 回退 unknown（不猜任务号）");
			assert.equal(raw.status, "unconfirmed");
			assert.notEqual(raw.status, "completed");
		});
		check("3(c) validateTabResult 拒绝「无 autoGenerated 的 unconfirmed」（防手工伪造未回报态）", () => {
			const v = validateTabResult({
				id: "tab_fake", taskId: "T", status: "unconfirmed", finishedAt: new Date().toISOString(), summary: "伪造",
			});
			assert.equal(v.ok, false, "无 autoGenerated 的 unconfirmed 必须被拒");
			assert.ok(v.errors.some((e) => e.includes("autoGenerated")), `错误必须点名 autoGenerated（实得 ${v.errors.join("; ")}）`);
		});
		check("3(d) validateTabResult 拒绝宽松 autoGenerated 形状（\"yes\"/1/false）", () => {
			for (const bad of ["yes", 1, false]) {
				const v = validateTabResult({
					id: "tab_x", taskId: "T", status: "unconfirmed", finishedAt: new Date().toISOString(), autoGenerated: bad,
				});
				assert.equal(v.ok, false, `autoGenerated=${JSON.stringify(bad)} 必须被拒（只允许严格 true）`);
			}
		});
		check("3(e) validateTabResult 拒绝 autoGenerated=true + 三态 status（双向不变量）", () => {
			const v = validateTabResult({
				id: "tab_x", taskId: "T", status: "completed", finishedAt: new Date().toISOString(), autoGenerated: true,
			});
			assert.equal(v.ok, false, "autoGenerated=true 只允许配合 unconfirmed");
		});
	} finally {
		rmSync(runsDir, { recursive: true, force: true });
	}
}

// ════════════ 4. 幂等：同一 runId 连续两次 ⇒ 只写一次 ═════════════════
console.log("4. 幂等：同一 runId 连续两次 agent_settled ⇒ 只写一次（finishedAt 时间戳不变）");
{
	const runsDir = mkdtempSync(join(tmpdir(), "tab-rf1-d-"));
	const runId = "tab_rf1_d";
	try {
		writeTabDispatch(runsDir, mkDispatch(runId));
		const pi = makeFakePi();
		registerTabTelemetry(pi, { tabRunId: runId, runsDir });
		await runOneTurn(pi, "第一轮结束");
		const first = readFileSync(tabResultPath(runsDir, runId), "utf8");
		const firstRaw = JSON.parse(first) as Record<string, unknown>;

		// 同一 runId 再 settle 两次（模拟重启/多轮回跳/事件重放）
		await pi.emit("agent_settled", {}, { isIdle: () => true });
		await new Promise((r) => setTimeout(r, 15)); // 确保即使重写 finishedAt 也会变
		await pi.emit("agent_settled", {}, { isIdle: () => true });

		check("4(a) 内容逐字节不变（只写一次）", () => {
			assert.equal(readFileSync(tabResultPath(runsDir, runId), "utf8"), first);
		});
		check("4(b) finishedAt 未被第二次 settle 刷新", () => {
			const raw = JSON.parse(readFileSync(tabResultPath(runsDir, runId), "utf8")) as Record<string, unknown>;
			assert.equal(raw.finishedAt, firstRaw.finishedAt);
		});
		check("4(c) 直接再调 writeSettlementFallback 也返回 skip-has-result（函数级幂等）", () => {
			assert.equal(writeSettlementFallback({ runsDir, runId, lastAssistantText: "again" }), "skip-has-result");
			assert.equal(readFileSync(tabResultPath(runsDir, runId), "utf8"), first);
		});
	} finally {
		rmSync(runsDir, { recursive: true, force: true });
	}
}

// ════════════ 5. 写失败 ⇒ 不抛到调用方 ═════════════════════════════════
console.log("5. 写失败（注入会抛的写函数）⇒ **不抛到调用方**（never-throw）");
{
	const runsDir = mkdtempSync(join(tmpdir(), "tab-rf1-e-"));
	const runId = "tab_rf1_e";
	const wiringRunId = "tab_rf1_e_wiring";
	try {
		writeTabDispatch(runsDir, mkDispatch(runId));
		writeTabDispatch(runsDir, mkDispatch(wiringRunId));

		// 5(c) 夹具：经真实接线（agent_settled）注入抛错写 —— 在这里先 await（check() 是同步的）
		const piWiring = makeFakePi();
		registerTabTelemetry(piWiring, {
			tabRunId: wiringRunId,
			runsDir,
			finishFallback: { writeJson: () => { throw new Error("wiring boom"); } },
		});
		let wiringThrew: unknown = null;
		try {
			await runOneTurn(piWiring, "回合结束");
		} catch (e) {
			wiringThrew = e;
		}

		check("5(a) 注入抛错的 writeJson ⇒ doesNotThrow 且返回 error", () => {
			let ret: string | undefined;
			assert.doesNotThrow(() => {
				ret = writeSettlementFallback({
					runsDir,
					runId,
					lastAssistantText: "x",
					io: { writeJson: () => { throw new Error("disk boom"); } },
				});
			}, "写入抛错绝不得穿透到调用方（tab 不能因此崩溃）");
			assert.equal(ret, "error");
		});
		check("5(b) 注入抛错的 exists ⇒ 同样不抛", () => {
			let ret: string | undefined;
			assert.doesNotThrow(() => {
				ret = writeSettlementFallback({
					runsDir,
					runId,
					io: { exists: () => { throw new Error("stat boom"); } },
				});
			});
			assert.equal(ret, "error");
		});
		check("5(c) 经真实接线（agent_settled）注入抛错写 ⇒ 事件派发不抛", () => {
			assert.equal(wiringThrew, null, `agent_settled 处理器必须 never-throw（实得：${String(wiringThrew)}）`);
		});
		check("5(d) 写失败后 state 仍正常写 waiting（兜底失败不影响正常遥测）", () => {
			const raw = JSON.parse(readFileSync(join(runsDir, `${wiringRunId}.state.json`), "utf8")) as Record<string, unknown>;
			assert.equal(raw.phase, "waiting");
			assert.equal(raw.terminal, false);
		});
		check("5(e) 写失败的 runId 不得留下 result.json（不写半截，也不沉黑）", () => {
			let exists = true;
			try {
				readFileSync(tabResultPath(runsDir, wiringRunId), "utf8");
			} catch { exists = false; }
			assert.equal(exists, false);
		});
	} finally {
		rmSync(runsDir, { recursive: true, force: true });
	}
}

// ════════════ 6. 无 dispatch 记录 ⇒ 不生成 ═════════════════════════════
console.log("6. 无 dispatch 记录的 runId ⇒ **不生成**（防误伤非派发会话；经 agent_settled 真实派发）");
{
	const runsDir = mkdtempSync(join(tmpdir(), "tab-rf1-f-"));
	const runId = "tab_rf1_nodisp";
	try {
		const pi = makeFakePi();
		registerTabTelemetry(pi, { tabRunId: runId, runsDir });
		await runOneTurn(pi, "我是手工开的会话，不是派发的 tab");

		check("6(a) 未生成 result.json", () => {
			let exists = true;
			try {
				readFileSync(tabResultPath(runsDir, runId), "utf8");
			} catch {
				exists = false;
			}
			assert.equal(exists, false, "无 dispatch 账本的会话不得被兜底");
		});
		check("6(b) 直调 writeSettlementFallback 返回 skip-no-dispatch", () => {
			assert.equal(writeSettlementFallback({ runsDir, runId, lastAssistantText: "x" }), "skip-no-dispatch");
		});
		check("6(c) 对照：补上 dispatch 记录后同形状即可生成（证明 6(a) 不是链路失效）", () => {
			writeTabDispatch(runsDir, mkDispatch(runId));
			assert.equal(writeSettlementFallback({ runsDir, runId, lastAssistantText: "x" }), "written");
			const raw = JSON.parse(readFileSync(tabResultPath(runsDir, runId), "utf8")) as Record<string, unknown>;
			assert.equal(raw.status, "unconfirmed");
		});
	} finally {
		rmSync(runsDir, { recursive: true, force: true });
	}
}

// ════════════ 7. 监管六态：terminal+resultMissing / unconfirmed ⇒ BLOCKED_USER ════════════
console.log("7. deriveTabSupervisionState：terminal+resultMissing ⇒ BLOCKED_USER（非 DONE）；unconfirmed+active ⇒ BLOCKED_USER");
{
	const ledger: FrontierSupervision = { runId: "tab_rf1", status: "active", epochPushes: 0 };

	check("7(a) phase=completed ∧ resultMissing=true ∧ 账本 active ⇒ BLOCKED_USER（不是 DONE）", () => {
		const st = deriveTabSupervisionState({ tab: mkTab({ phase: "completed", resultMissing: true }), ledger, attention: 0 });
		assert.equal(st, "BLOCKED_USER");
		assert.notEqual(st, "DONE", "「终态但没 result」不得判 DONE（DONE = 可回收关账）");
	});
	check("7(b) 对照：phase=completed ∧ resultMissing=false ⇒ DONE（证明 7(a) 是 resultMissing 分界）", () => {
		assert.equal(
			deriveTabSupervisionState({ tab: mkTab({ phase: "completed", resultMissing: false }), ledger, attention: 0 }),
			"DONE",
		);
	});
	check('7(c) phase="unconfirmed"（兜底形状）∧ 账本 active ⇒ BLOCKED_USER（非 STALLED、非 DONE）', () => {
		const st = deriveTabSupervisionState({ tab: mkTab({ phase: "unconfirmed", resultMissing: true }), ledger, attention: 0 });
		assert.equal(st, "BLOCKED_USER");
		assert.notEqual(st, "DONE");
		assert.notEqual(st, "STALLED", "未回报不是「停滞」：推它没用，需要人核实");
	});
	check("7(d) 无账本 ⇒ 仍 NOT_MONITORED（兜底不得绕过 opt-in 静默门）", () => {
		assert.equal(
			deriveTabSupervisionState({ tab: mkTab({ phase: "unconfirmed", resultMissing: true }), ledger: undefined, attention: 0 }),
			"NOT_MONITORED",
		);
	});
	check("7(e) 账本 paused/optOut 优先于 7(a)/7(c)（用户显式意图不被兜底覆盖）", () => {
		assert.equal(
			deriveTabSupervisionState({ tab: mkTab({ phase: "unconfirmed" }), ledger: { ...ledger, status: "paused" }, attention: 0 }),
			"PAUSED_USER",
		);
		assert.equal(
			deriveTabSupervisionState({ tab: mkTab({ phase: "unconfirmed" }), ledger: { ...ledger, optOut: true }, attention: 0 }),
			"NOT_MONITORED",
		);
	});
	check("7(f) stop=aborted 不并入（主动中断下的「没回报」是预期，不报待审）", () => {
		assert.notEqual(
			deriveTabSupervisionState({ tab: mkTab({ phase: "unconfirmed", stop: "aborted" }), ledger, attention: 0 }),
			"BLOCKED_USER",
		);
	});
}

// ════════════ 8. 下游接线：classifyDispatch 不得把兜底当成 completed ════════════
console.log("8. classifyDispatch / event-bus 唤醒文案：兜底结果不得被伪装成 completed 或「已完成」");
{
	const runsDir = mkdtempSync(join(tmpdir(), "tab-rf1-g-"));
	const runId = "tab_rf1_visible";
	try {
		writeTabDispatch(runsDir, mkDispatch(runId));
		const pi = makeFakePi();
		registerTabTelemetry(pi, { tabRunId: runId, runsDir });
		await runOneTurn(pi, "我写完了但忘了回报");

		check('8(a) classifyDispatch：兜底 result 必须可见（hiddenKind=null）、attention=true、phase 不得是 completed', () => {
			const note = classifyDispatch({ id: runId, taskId: "RF-1", dispatchedAt: new Date().toISOString() } as TabDispatchRecord, runsDir);
			assert.equal(note.phase, "unconfirmed", `phase 必须反映兜底态（实得 ${note.phase}）`);
			assert.notEqual(note.phase, "completed", "不得把「没回报」伪装成 completed（RF-1 硬约束 1）");
			assert.equal(note.hiddenKind, null, "兜底必须可见，不得被 hidden 摘掉");
			assert.equal(note.attention, true, "兜底必须待审（attention）");
		});
		check("8(b) event-bus 唤醒文案：不得说「已完成」，须说明未调用 tab-finish", () => {
			const sent: string[] = [];
			// 真实接线前置：event-bus 只向「派发该 tab 的会话」注入（links 溯源）
			const linksPath = join(runsDir, "links.jsonl");
			writeFileSync(linksPath, JSON.stringify({
				sessionId: "session-rf1", kind: "tab", targetId: runId,
				detail: "task=RF-1", at: new Date().toISOString(), pid: 1,
			}) + "\n", "utf8");
			setCurrentSessionId("session-rf1");
			const woke = onTabResultFile(runsDir, `${runId}.result.json`, {
				runsDir, linksPath, toast: false, autoReclaim: true,
				sendUserMessage: (c: string) => { sent.push(c); },
			} as never);
			setCurrentSessionId(undefined);
			assert.equal(woke, true, "兜底结果必须能唤醒主会话（false = 仍是 dead code）");
			assert.equal(sent.length, 1, `兜底结果必须注入恰好 1 条唤醒（实得 ${sent.length}）`);
			assert.ok(!sent[0].includes("已完成"), `兜底文案不得含「已完成」：${sent[0].slice(0, 120)}`);
			assert.ok(sent[0].includes("未调用 tab-finish"), "文案必须点名未调用 tab-finish");
		});
	} finally {
		rmSync(runsDir, { recursive: true, force: true });
	}
}

// ══════ 10. 常驻身份豁免：lms-* / master-* 不写兜底（2026-10-18 GLM D-3）══════
// 根因：runtime/local-master-launch.ts:249 明令 local master 不要调 tab-finish、不要退出，
// 其账本 taskId = `lms-<scope>`（:276-278）。以前兜底会每次 settle 给健康 local master 写一条
// **永久** unconfirmed，其 attention:true（frontier-carriers.ts:203）会把同仓全部受监管 tab
// 污染成 BLOCKED_USER。本组必须经**真实入口** pi.emit("agent_settled") 验证（R-4）。
console.log("10. 常驻身份豁免：taskId=lms-* / master-* ⇒ 真 agent_settled 后不写兜底 result");
{
	const runsDir = mkdtempSync(join(tmpdir(), "tab-rf1-j-"));
	const cases: Array<[string, string]> = [
		["tab_rf1_lms", "lms-battlesandbox"],
		["tab_rf1_master", "master-S2"],
	];
	try {
		for (const [runId, taskId] of cases) {
			writeTabDispatch(runsDir, mkDispatch(runId, taskId));
			const pi = makeFakePi();
			registerTabTelemetry(pi, { tabRunId: runId, runsDir });
			await runOneTurn(pi, "local master 常驻回合 settle（设计行为，不是忘回报）");
		}

		check("10(a) taskId=\"lms-battlesandbox\" ⇒ 经 agent_settled 后不存在 result 文件", () => {
			assert.equal(existsSync(tabResultPath(runsDir, "tab_rf1_lms")), false, "local master 不得被兜底写 unconfirmed");
		});
		check("10(b) taskId=\"master-S2\" ⇒ 同样不写 result 文件", () => {
			assert.equal(existsSync(tabResultPath(runsDir, "tab_rf1_master")), false, "master 派发不得被兜底写 unconfirmed");
		});
		check("10(c) 对照：taskId=\"GFIX-2\"（普通派发）⇒ 仍写 unconfirmed（防豁免过宽）", () => {
			const runId = "tab_rf1_normal";
			writeTabDispatch(runsDir, mkDispatch(runId, "GFIX-2"));
			assert.equal(writeSettlementFallback({ runsDir, runId, lastAssistantText: "普通 tab" }), "written");
			const raw = JSON.parse(readFileSync(tabResultPath(runsDir, runId), "utf8")) as Record<string, unknown>;
			assert.equal(raw.status, "unconfirmed");
			assert.equal(raw.taskId, "GFIX-2");
		});
		check("10(d) 函数级：直调返回 skip-persistent-identity，且未落盘（两前缀均如此）", () => {
			const runA = "tab_rf1_lms2";
			const runB = "tab_rf1_master2";
			writeTabDispatch(runsDir, mkDispatch(runA, "lms-other-scope"));
			writeTabDispatch(runsDir, mkDispatch(runB, "master-X9"));
			assert.equal(writeSettlementFallback({ runsDir, runId: runA, lastAssistantText: "x" }), "skip-persistent-identity");
			assert.equal(writeSettlementFallback({ runsDir, runId: runB, lastAssistantText: "x" }), "skip-persistent-identity");
			assert.equal(existsSync(tabResultPath(runsDir, runA)), false);
			assert.equal(existsSync(tabResultPath(runsDir, runB)), false);
		});
	} finally {
		rmSync(runsDir, { recursive: true, force: true });
	}
}

// ── 汇总 + 清理 ───────────────────────────────────────────────────
// ══════ 9. 连带（最小必要）：unconfirmed 兑底结果不得作为归档证据 ══════
console.log("9. archiveStaleTabRuns：unconfirmed 兑底结果 ≠ 终态证据（沉默但活着的 tab 不得被移出活跃目录）");
{
	const runsDir = mkdtempSync(join(tmpdir(), "tab-rf1-i-"));
	try {
		// (a) 超龄 dispatch + 兑底 unconfirmed result（经真实 agent_settled 接线写入）+ 无 state
		//     ⇒ 修前：证据③「存在 result 文件」= true ⇒ 被归档（RF-1 信号从活跃视图消失）；修后：不归档
		const silent = "tab_rf1_silent_aged";
		writeTabDispatch(runsDir, { ...mkDispatch(silent), dispatchedAt: new Date(Date.now() - 100 * 3600 * 1000).toISOString() });
		const piS = makeFakePi();
		registerTabTelemetry(piS, { tabRunId: silent, runsDir });
		await runOneTurn(piS, "长程沉默回合");
		archiveStaleTabRuns(runsDir, 72);
		check("9(a) unconfirmed 兑底 + 超龄 ⇒ 不得归档（账本留在活跃目录）", () => {
			assert.ok(existsSync(join(runsDir, `${silent}.json`)), "沉默但未终态的 tab 不得被移入 _archived（否则 frontier/supervision 丢失载体）");
			assert.equal(existsSync(join(runsDir, "_archived", `${silent}.json`)), false);
		});

		// (b) 对照：真 tab-finish completed result + 超龄 ⇒ 仍归档（旧行为不变，非一刀切禁归档）
		const done = "tab_rf1_done_aged";
		writeTabDispatch(runsDir, { ...mkDispatch(done), dispatchedAt: new Date(Date.now() - 100 * 3600 * 1000).toISOString() });
		writeJsonAtomic(tabResultPath(runsDir, done), {
			id: done, taskId: "TASK-RF1-DONE", status: "completed", finishedAt: new Date(Date.now() - 99 * 3600 * 1000).toISOString(), summary: "真终态",
		});
		archiveStaleTabRuns(runsDir, 72);
		check("9(b) 对照：真 completed result + 超龄 ⇒ 正常归档（证据③对真三态不变）", () => {
			assert.ok(existsSync(join(runsDir, "_archived", `${done}.json`)), "真终态必须能清理（否则与 RF-1 前行为回退）");
		});
	} finally {
		rmSync(runsDir, { recursive: true, force: true });
	}
}

try {
	rmSync(process.env.PI_RUNTIME_DIR ?? "", { recursive: true, force: true });
} catch { /* 临时 runtime 目录清理失败不影响结果 */ }
console.log("");
if (failed > 0) {
	console.error(`_test_tab_report_fallback: FAILED (${failed} failed / ${passed} passed)`);
	process.exit(1);
}
console.log(`_test_tab_report_fallback: all ${passed} checks passed`);

